<?php
session_start();if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}require_once __DIR__.'/../config/config.php';
$userId=(int)$_SESSION['user_id'];$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare("SELECT * FROM exchanges WHERE exchange_id=? AND owner_id=? AND status<>'completed'");$stmt->execute([$id,$userId]);$item=$stmt->fetch(PDO::FETCH_ASSOC);if(!$item){http_response_code(403);exit('ไม่พบโพสต์ หรือคุณไม่มีสิทธิ์แก้ไขโพสต์นี้');}
$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $isbn=preg_replace('/[^0-9Xx]/','',$_POST['isbn']??'');$title=trim($_POST['title']??'');$condition=$_POST['condition_percent']??'';$wanted=$_POST['wanted_type']??'';$shipping=$_POST['shipping']??[];
 if(!in_array(strlen($isbn),[10,13],true))$error='กรุณากรอก ISBN 10 หรือ 13 หลัก';elseif($title==='')$error='กรุณากรอกชื่อหนังสือ';elseif(!in_array($condition,['99','90','80','70'],true))$error='กรุณาเลือกสภาพหนังสือ';elseif(!in_array($wanted,['specific','category','any'],true))$error='กรุณาเลือกรูปแบบที่ต้องการแลก';elseif(!$shipping)$error='กรุณาเลือกวิธีจัดส่งอย่างน้อย 1 วิธี';
 $paths=[];$dir=__DIR__.'/uploads/exchanges';if(!is_dir($dir))mkdir($dir,0775,true);foreach(['image_cover','image_back','image_inside','image_edge'] as $field){$paths[$field]=$item[$field];if(!empty($_FILES[$field]['name'])&&$_FILES[$field]['error']===UPLOAD_ERR_OK){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$field]['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext){$error='รองรับเฉพาะรูป JPG, PNG และ WEBP';break;}$name='exchange_'.bin2hex(random_bytes(8)).'.'.$ext;if(move_uploaded_file($_FILES[$field]['tmp_name'],$dir.'/'.$name))$paths[$field]='uploads/exchanges/'.$name;}}
 if(!$error){$update=$pdo->prepare("UPDATE exchanges SET isbn=?,title=?,author=?,category=?,condition_percent=?,defect_types=?,image_cover=?,image_back=?,image_inside=?,image_edge=?,wanted_type=?,wanted_detail=?,shipping_methods=?,story_reason=? WHERE exchange_id=? AND owner_id=?");$update->execute([$isbn,$title,trim($_POST['author']??''),trim($_POST['category']??''),$condition,implode(',',$_POST['defects']??[]),$paths['image_cover'],$paths['image_back'],$paths['image_inside'],$paths['image_edge'],$wanted,trim($_POST['wanted_detail']??''),implode(',',$shipping),trim($_POST['story_reason']??''),$id,$userId]);$stmt->execute([$id,$userId]);$item=$stmt->fetch(PDO::FETCH_ASSOC);$success='บันทึกการแก้ไขโพสต์แลกเปลี่ยนเรียบร้อยแล้ว';}
}
function ex(string $v):string{return htmlspecialchars($v);}function exImg(?string $v):string{if(!$v)return '';$v=ltrim(str_replace('\\','/',$v),'/');return preg_match('#^https?://#',$v)?$v:(str_starts_with($v,'uploads/')?'/pages/'.$v:'/assets/image/'.$v);}$defects=array_filter(explode(',',$item['defect_types']??''));$ships=array_filter(explode(',',$item['shipping_methods']??''));
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>แก้ไขโพสต์แลกเปลี่ยน - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>
*{box-sizing:border-box}.page{max-width:980px;margin:auto;padding:40px 24px 80px}.back{color:var(--secondary-color);text-decoration:none}.title{font-size:32px;color:var(--secondary-color);margin:18px 0 28px}.section{border:1px solid #dfd6ce;border-radius:14px;padding:26px;margin-bottom:18px;background:#fff}.section h2{font-size:19px;color:var(--secondary-color);margin:0 0 20px}.grid{display:grid;grid-template-columns:repeat(2, 1fr) repeat(2, 1fr);gap:17px}.field{margin-bottom:16px}.field label{display:block;font-weight:600;color:#685f59;margin-bottom:7px}.field input,.field textarea,.field select{width:100%;padding:12px;border:1px solid #ccd3c5;border-radius:8px;font:inherit}.field textarea{min-height:105px}.choices,.checks{display:flex;gap:10px;flex-wrap:wrap}.choices label,.checks label{padding:12px 15px;border:1px solid #d8d2ca;border-radius:8px}.images{display:grid;grid-template-columns:repeat(2,1fr);gap:17px}.image{border:2px dashed #cbd2c4;border-radius:11px;padding:12px;text-align:center}.image img{width:100%;height:205px;object-fit:contain;background:#f7f3f0;border-radius:8px;display:block;margin:9px 0}.image input{width:100%}.actions{display:flex;gap:12px}.btn{min-width:190px;height:50px;border-radius:8px;font:inherit;font-weight:600;display:grid;place-items:center;text-decoration:none}.save{border:0;background:var(--secondary-color);color:#fff}.cancel{border:1px solid var(--secondary-color);color:var(--secondary-color)}.notice{padding:14px;border-radius:8px;margin-bottom:17px}.ok{background:#e8f4e3;color:#46723d}.bad{background:#fde6e1;color:#a44b44}@media(max-width:700px){.page{padding:28px 15px 65px}.grid,.images{grid-template-columns:repeat(2, 1fr)}.actions{flex-direction:column}.btn{width:100%}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="page"><a class="back" href="/pages/profile.php?tab=exchange">← กลับหน้าโปรไฟล์</a><h1 class="title">แก้ไขโพสต์แลกเปลี่ยนหนังสือ</h1><?php if($success):?><div class="notice ok"><?=ex($success)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=ex($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><section class="section"><h2>1. รายละเอียดหนังสือ</h2><div class="grid"><div class="field"><label>ISBN *</label><input name="isbn" required value="<?=ex($item['isbn']??'')?>"></div><div class="field"><label>ชื่อหนังสือ *</label><input name="title" required value="<?=ex($item['title'])?>"></div><div class="field"><label>ผู้เขียน</label><input name="author" value="<?=ex($item['author']??'')?>"></div><div class="field"><label>หมวดหมู่</label><input name="category" value="<?=ex($item['category']??'')?>"></div></div></section>
<section class="section"><h2>2. สภาพหนังสือ</h2><div class="choices"><?php foreach(['99'=>'99% เหมือนใหม่','90'=>'90% ดี','80'=>'80% พอใช้','70'=>'ต่ำกว่า 70%'] as $v=>$label):?><label><input type="radio" name="condition_percent" value="<?=$v?>" <?=$item['condition_percent']===$v?'checked':''?>> <?=$label?></label><?php endforeach;?></div><div class="checks" style="margin-top:15px"><?php foreach(['จุดเหลือง','รอยพับ','ลายเซ็นเจ้าของเดิม','สันกาวหลุด','รอยไฮไลต์'] as $d):?><label><input type="checkbox" name="defects[]" value="<?=$d?>" <?=in_array($d,$defects,true)?'checked':''?>> <?=$d?></label><?php endforeach;?></div></section>
<section class="section"><h2>3. รูปภาพสภาพจริง</h2><div class="images"><?php foreach(['image_cover'=>'หน้าปก','image_back'=>'หลังปก','image_inside'=>'ด้านใน','image_edge'=>'สัน/ขอบ'] as $field=>$label):?><label class="image"><strong><?=$label?></strong><img id="preview-<?=$field?>" src="<?=ex(exImg($item[$field]??null))?>" alt="<?=$label?>"><input type="file" name="<?=$field?>" accept="image/*" onchange="previewExchange(this,'<?=$field?>')"></label><?php endforeach;?></div></section>
<section class="section"><h2>4. ความต้องการแลกเปลี่ยน</h2><div class="choices"><?php foreach(['specific'=>'หนังสือเฉพาะเล่ม','category'=>'ตามหมวดหมู่','any'=>'เปิดรับทุกข้อเสนอ'] as $v=>$label):?><label><input type="radio" name="wanted_type" value="<?=$v?>" <?=$item['wanted_type']===$v?'checked':''?>> <?=$label?></label><?php endforeach;?></div><div class="field" style="margin-top:15px"><label>หนังสือหรือหมวดหมู่ที่กำลังตามหา</label><textarea name="wanted_detail"><?=ex($item['wanted_detail']??'')?></textarea></div></section>
<section class="section"><h2>5. วิธีจัดส่ง</h2><div class="checks"><?php foreach(['Thai Post','Flash Express','J&T Express','นัดรับ'] as $s):?><label><input type="checkbox" name="shipping[]" value="<?=$s?>" <?=in_array($s,$ships,true)?'checked':''?>> <?=$s?></label><?php endforeach;?></div></section><section class="section"><h2>6. เรื่องราวของหนังสือ</h2><div class="field"><textarea name="story_reason"><?=ex($item['story_reason']??'')?></textarea></div></section><div class="actions"><button class="btn save" type="submit">บันทึกการแก้ไข</button><a class="btn cancel" href="/pages/profile.php?tab=exchange">ยกเลิก</a></div></form></main><?php require __DIR__.'/../components/footer.php';?><script>const exchangeUrls={};function previewExchange(input,key){const file=input.files&&input.files[0];if(!file)return;if(exchangeUrls[key])URL.revokeObjectURL(exchangeUrls[key]);exchangeUrls[key]=URL.createObjectURL(file);document.getElementById('preview-'+key).src=exchangeUrls[key]}</script></body></html>
